  if (LIVE.ui) { clearInterval(LIVE.ui); LIVE.ui = null; }
  if (LIVE.watchId != null && GPS_AVAILABLE) { navigator.geolocation.clearWatch(LIVE.watchId); LIVE.watchId = null; }
